class Solution:
    def findColumnWidth(self, grid: list[list[int]]) -> list[int]:
        m, n = len(grid), len(grid[0])
        ans = []
        for c in range(n):
            max_w = max(len(str(grid[r][c])) for r in range(m))
            ans.append(max_w)
        return ans

class Solution {
public:
    std::vector<int> findColumnWidth(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        std::vector<int> ans(n, 0);
        for (int c = 0; c < n; ++c) {
            int max_w = 0;
            for (int r = 0; r < m; ++r) {
                max_w = std::max(max_w, (int)std::to_string(grid[r][c]).size());
            }
            ans[c] = max_w;
        }
        return ans;
    }
};

class Solution {
    public int[] findColumnWidth(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[] ans = new int[n];
        for (int c = 0; c < n; c++) {
            int maxW = 0;
            for (int r = 0; r < m; r++) {
                maxW = Math.max(maxW, String.valueOf(grid[r][c]).length());
            }
            ans[c] = maxW;
        }
        return ans;
    }
}

var findColumnWidth = function(grid) {
    const m = grid.length, n = grid[0].length;
    const ans = new Int32Array(n);
    for (let c = 0; c < n; c++) {
        let maxW = 0;
        for (let r = 0; r < m; r++) {
            maxW = Math.max(maxW, String(grid[r][c]).length);
        }
        ans[c] = maxW;
    }
    return Array.from(ans);
};
